const cfg = $input.first().json;
const text = (value) => typeof value === 'string' ? value.trim() : '';
let advancedInput;
try { advancedInput = JSON.parse(text(cfg.advancedInputJson) || '{}'); }
catch (error) { throw new Error(`Configuration: advancedInputJson must be valid JSON (${error.message})`); }
if (!advancedInput || typeof advancedInput !== 'object' || Array.isArray(advancedInput)) throw new Error('Configuration: advancedInputJson must contain one JSON object');
if (text(cfg.actorBuild) !== 'latest') throw new Error('Configuration: this template supports exact Actor build latest');
const deliveryChannel = text(cfg.deliveryChannel).toLowerCase();
if (!new Set(['slack', 'telegram', 'email']).has(deliveryChannel)) throw new Error('Configuration: deliveryChannel must be slack, telegram, or email');
const deliveryTarget = text(cfg.deliveryTarget);
if (!deliveryTarget || deliveryTarget.startsWith('REPLACE_WITH_')) throw new Error('Configuration: replace deliveryTarget with a Slack channel ID, Telegram chat ID, or email address');
const emailFrom = text(cfg.emailFrom);
if (deliveryChannel === 'email' && (!emailFrom.includes('@') || emailFrom.startsWith('REPLACE_WITH_'))) throw new Error('Configuration: email delivery requires a verified emailFrom address');
const dedupeScope = text(cfg.dedupeScope);
if (!dedupeScope || dedupeScope.startsWith('REPLACE_WITH_')) throw new Error('Configuration: replace dedupeScope with a stable opaque name for this alert');
const maxItems = Number(cfg.maxItems);
if (!Number.isInteger(maxItems) || maxItems < 1 || maxItems > 25) throw new Error('Configuration: maxItems must be an integer from 1 to 25');
const chargeCap = Number(cfg.maxTotalChargeUsd);
if (!Number.isFinite(chargeCap) || chargeCap <= 0 || chargeCap > 1) throw new Error('Configuration: maxTotalChargeUsd must be greater than 0 and at most 1');
const actorInput = {
  schemaVersion: 'nomad-agent-job-search-input-v1',
  keyword: text(cfg.keyword),
  location: text(cfg.location),
  postedWithin: text(cfg.postedWithin),
  workArrangements: text(cfg.workArrangementsCsv).split(',').map(value => value.trim()).filter(Boolean),
  maxItems,
  translateToEnglish: false,
  aiEnrichment: { enabled: false, accuracy: 'silver' },
  includeRaw: false,
  dedupe: { enabled: true, key: dedupeScope },
  analyticsEnabled: false,
  ...advancedInput,
  maxItems,
  dedupe: { enabled: true, key: dedupeScope },
};
if (actorInput.schemaVersion !== 'nomad-agent-job-search-input-v1') throw new Error('Configuration: actor input schemaVersion must be nomad-agent-job-search-input-v1');
if (!new Set(['1h', '24h', '7d', '30d', 'any']).has(actorInput.postedWithin)) throw new Error('Configuration: postedWithin must be 1h, 24h, 7d, 30d, or any');
if (!Array.isArray(actorInput.workArrangements) || actorInput.workArrangements.some(value => !new Set(['remote', 'hybrid', 'onsite']).has(value))) throw new Error('Configuration: workArrangements must contain only remote, hybrid, or onsite');
return [{ json: { ...cfg, deliveryChannel, deliveryTarget, emailFrom, actorInput } }];

const ROOTS = ['custom', 'data', 'identity', 'llm', 'raw', 'schemaVersion'];
const objectOrEmpty = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const incoming = $input.all().map(item => item.json);
const records = [];
for (const value of incoming) {
  if (Array.isArray(value)) records.push(...value);
  else if (value && Array.isArray(value.body)) records.push(...value.body);
  else if (value && value.schemaVersion === 'nomad-agent-job-v1') records.push(value);
  else if (value && Object.keys(value).length === 0) continue;
  else throw new Error('Apify response did not contain nomad-agent-job-v1 records');
}
const seen = new Set();
const output = [];
for (const record of records) {
  const actualRoots = Object.keys(record).sort();
  if (JSON.stringify(actualRoots) !== JSON.stringify(ROOTS)) throw new Error(`Actor row has unexpected roots: ${actualRoots.join(', ')}`);
  if (record.schemaVersion !== 'nomad-agent-job-v1') throw new Error(`Unsupported schemaVersion: ${record.schemaVersion}`);
  const identity = objectOrEmpty(record.identity);
  if (identity.source !== 'linkedin') throw new Error(`Unexpected job source: ${identity.source}`);
  if (typeof identity.externalId !== 'string' || !identity.externalId.trim()) throw new Error('identity.externalId must be a non-empty string');
  const jobKey = `${identity.source}:${identity.externalId.trim()}`;
  if (seen.has(jobKey)) continue;
  seen.add(jobKey);
  const data = objectOrEmpty(record.data);
  const company = objectOrEmpty(data.company);
  const application = objectOrEmpty(data.application);
  const locations = Array.isArray(data.locations) ? data.locations : [];
  const locationText = locations.map(value => objectOrEmpty(value)).map(value => value.raw || [value.city, value.region, value.countryName].filter(Boolean).join(', ')).filter(Boolean).join(' | ') || null;
  const title = typeof data.title === 'string' && data.title.trim() ? data.title.trim() : 'Untitled LinkedIn job';
  const url = application.url || identity.url || null;
  const lines = ['New LinkedIn job', title];
  if (company.name) lines.push(`Company: ${company.name}`);
  if (locationText) lines.push(`Location: ${locationText}`);
  if (application.postedAt) lines.push(`Posted: ${application.postedAt}`);
  if (url) lines.push(`Apply: ${url}`);
  lines.push(`Job key: ${jobKey}`);
  output.push({ json: { jobKey, title, companyName: company.name ?? null, locationText, postedAt: application.postedAt ?? null, url, message: lines.join('\n'), emailSubject: `New LinkedIn job: ${title}` } });
}
return output;
